    "Picks up where you left off ({0})" to Tr(ja = "やめた ところから つづけます ({0})", fr = "Reprend là où vous en étiez ({0})", de = "Macht weiter, wo du aufgehört hast ({0})", it = "Riprende da dove eri rimasto ({0})", es = "Sigue donde lo dejaste ({0})"),
