    "PokéDaisy {0} is out - you have {1}." to Tr(ja = "PokéDaisy {0}が でました - いまは {1}です。", fr = "PokéDaisy {0} est sorti - vous avez la {1}.", de = "PokéDaisy {0} ist da - du hast {1}.", it = "È uscito PokéDaisy {0} - hai la {1}.", es = "Ya salió PokéDaisy {0} - tienes la {1}."),
