    "PokeDaisy can't read {0} - allow All files access, then launch again" to Tr(ja = "PokeDaisyは {0}を よめません - 「すべての ファイルへの アクセス」を きょかして もういちど ひらいてください", fr = "PokeDaisy ne peut pas lire {0} - autorisez l'accès à tous les fichiers, puis relancez", de = "PokeDaisy kann {0} nicht lesen - erlaube den Zugriff auf alle Dateien und starte neu", it = "PokeDaisy non può leggere {0} - consenti l'accesso a tutti i file, poi riavvia", es = "PokeDaisy no puede leer {0} - permite el acceso a todos los archivos y vuelve a abrirlo"),
