    "No ROM found. Put a .gba (or .zip / .7z) in {0}" to Tr(ja = "ROMが ありません。 .gba (または .zip / .7z)を {0} に いれてください", fr = "Aucune ROM trouvée. Placez un .gba (ou .zip / .7z) dans {0}", de = "Kein ROM gefunden. Lege eine .gba (oder .zip / .7z) in {0}", it = "Nessuna ROM trovata. Metti un .gba (o .zip / .7z) in {0}", es = "No se encontró ninguna ROM. Pon un .gba (o .zip / .7z) en {0}"),
