    "Slot {0}: save failed" to Tr(ja = "スロット {0}: ほぞん しっぱい", fr = "Emplacement {0} : échec", de = "Slot {0}: Speichern fehlgeschlagen", it = "Slot {0}: salvataggio non riuscito", es = "Ranura {0}: no se pudo guardar"),
    "Loaded slot {0}" to Tr(ja = "スロット {0}を よみこみました", fr = "Emplacement {0} chargé", de = "Slot {0} geladen", it = "Slot {0} caricato", es = "Ranura {0} cargada"),
