    "Undid save (slot {0})" to Tr(ja = "ほぞんを とりけしました (スロット {0})", fr = "Enregistrement annulé ({0})", de = "Speichern rückgängig (Slot {0})", it = "Salvataggio annullato (slot {0})", es = "Guardado deshecho (ranura {0})"),
    "Nothing to undo" to Tr(ja = "とりけす ものが ありません", fr = "Rien à annuler", de = "Nichts rückgängig zu machen", it = "Niente da annullare", es = "Nada que deshacer"),
