    "Slot {0} (used)" to Tr(ja = "スロット {0} (しようちゅう)", fr = "Emplacement {0} (utilisé)", de = "Slot {0} (belegt)", it = "Slot {0} (usato)", es = "Ranura {0} (usada)"),
    "Slot {0} (empty)" to Tr(ja = "スロット {0} (から)", fr = "Emplacement {0} (vide)", de = "Slot {0} (leer)", it = "Slot {0} (vuoto)", es = "Ranura {0} (vacía)"),
    // First-time setup
    "WELCOME TO POKéDAISY" to Tr(ja = "POKéDAISYへ ようこそ", fr = "BIENVENUE DANS POKéDAISY", de = "WILLKOMMEN BEI POKéDAISY", it = "BENVENUTO IN POKéDAISY", es = "BIENVENIDO A POKéDAISY"),
    "SKIP" to Tr(ja = "スキップ", fr = "PASSER", de = "ÜBERSPRINGEN", it = "SALTA", es = "OMITIR"),
    "DONE" to Tr(ja = "おわり", fr = "TERMINÉ", de = "FERTIG", it = "FINE", es = "LISTO"),
    "NEXT|continue" to Tr(ja = "つぎへ", fr = "SUIVANT", de = "WEITER", it = "AVANTI", es = "SIGUIENTE"),
    "YOUR ROMS FOLDER" to Tr(ja = "ROMフォルダ", fr = "VOTRE DOSSIER DE ROM", de = "DEIN ROM-ORDNER", it = "LA TUA CARTELLA ROM", es = "TU CARPETA DE ROM"),
    "Pick the folder you keep your games in. PokéDaisy adds every game from it that the second screen supports, plays them right where they are (nothing is copied), and looks for new ones each time you open the app." to Tr(ja = "ゲームを いれている フォルダを えらんでください。 PokéDaisyは サブがめんが たいおうする ゲームを すべて ついかし、 その ばしょの まま プレイして (コピーは しません)、 アプリを ひらく たびに あたらしい ゲームを さがします。", fr = "Choisissez le dossier où vous rangez vos jeux. PokéDaisy ajoute chaque jeu pris en charge par le 2nd écran, le lance sur place (rien n'est copié) et cherche les nouveaux à chaque ouverture de l'appli.", de = "Wähle den Ordner mit deinen Spielen. PokéDaisy fügt jedes Spiel daraus hinzu, das der 2. Bildschirm unterstützt, spielt es direkt dort (nichts wird kopiert) und sucht bei jedem App-Start nach neuen.", it = "Scegli la cartella dove tieni i tuoi giochi. PokéDaisy aggiunge ogni gioco supportato dal secondo schermo, lo avvia lì dov'è (nulla viene copiato) e cerca quelli nuovi ogni volta che apri l'app.", es = "Elige la carpeta donde guardas tus juegos. PokéDaisy añade cada juego compatible con la 2.ª pantalla, lo abre donde está (no se copia nada) y busca nuevos cada vez que abres la app."),
    "This is optional: skip it and add games one at a time with + in the library. You can link a folder later in SETTINGS > FOLDERS." to Tr(ja = "これは しなくても だいじょうぶ: スキップして ライブラリの + で ひとつずつ ついか できます。 フォルダは あとで せってい > フォルダ でも つなげます。", fr = "C'est facultatif : passez et ajoutez les jeux un par un avec + dans la bibliothèque. Vous pourrez lier un dossier plus tard dans OPTIONS > DOSSIERS.", de = "Das ist optional: Überspring es und füge Spiele einzeln mit + in der Bibliothek hinzu. Einen Ordner kannst du später unter OPTIONEN > ORDNER verknüpfen.", it = "È facoltativo: saltalo e aggiungi i giochi uno alla volta con + nella libreria. Puoi collegare una cartella più tardi in OPZIONI > CARTELLE.", es = "Es opcional: omítelo y añade juegos de uno en uno con + en la biblioteca. Puedes vincular una carpeta más tarde en AJUSTES > CARPETAS."),
    "Android asks you to allow All files access first, so PokéDaisy can open games and saves outside its own folder. Turn it on and come back here." to Tr(ja = "さきに Androidが 「すべての ファイルへの アクセス」の きょかを もとめます。 PokéDaisyが じぶんの フォルダの そとの ゲームや セーブを ひらく ためです。 オンにして ここへ もどってください。", fr = "Android vous demande d'abord d'autoriser l'accès à tous les fichiers, pour que PokéDaisy puisse ouvrir jeux et sauvegardes hors de son dossier. Activez-le et revenez ici.", de = "Android fragt zuerst nach dem Zugriff auf alle Dateien, damit PokéDaisy Spiele und Speicherstände außerhalb seines Ordners öffnen kann. Schalte ihn ein und komm hierher zurück.", it = "Android chiede prima di consentire l'accesso a tutti i file, così PokéDaisy può aprire giochi e salvataggi fuori dalla sua cartella. Attivalo e torna qui.", es = "Android te pide primero permitir el acceso a todos los archivos, para que PokéDaisy pueda abrir juegos y partidas fuera de su carpeta. Actívalo y vuelve aquí."),
    "LOOKING FOR GAMES… {0} / {1}" to Tr(ja = "ゲームを さがしちゅう… {0} / {1}", fr = "RECHERCHE DE JEUX… {0} / {1}", de = "SUCHE SPIELE… {0} / {1}", it = "CERCO GIOCHI… {0} / {1}", es = "BUSCANDO JUEGOS… {0} / {1}"),
    "No supported games in there. Pick another folder, or skip and add games with + later." to Tr(ja = "たいおうする ゲームが ありません。 べつの フォルダを えらぶか、 スキップして あとで + で ついかしてください。", fr = "Aucun jeu pris en charge ici. Choisissez un autre dossier, ou passez et ajoutez des jeux avec + plus tard.", de = "Keine unterstützten Spiele darin. Wähle einen anderen Ordner oder überspring es und füge später Spiele mit + hinzu.", it = "Nessun gioco supportato qui. Scegli un'altra cartella, o salta e aggiungi i giochi con + più tardi.", es = "No hay juegos compatibles ahí. Elige otra carpeta, u omite y añade juegos con + más tarde."),
    "FOUND 1 GAME" to Tr(ja = "ゲームを 1こ みつけた", fr = "1 JEU TROUVÉ", de = "1 SPIEL GEFUNDEN", it = "1 GIOCO TROVATO", es = "1 JUEGO ENCONTRADO"),
    "FOUND {0} GAMES" to Tr(ja = "ゲームを {0}こ みつけた", fr = "{0} JEUX TROUVÉS", de = "{0} SPIELE GEFUNDEN", it = "{0} GIOCHI TROVATI", es = "{0} JUEGOS ENCONTRADOS"),
    "GAME SAVES" to Tr(ja = "セーブデータ", fr = "SAUVEGARDES", de = "SPEICHERSTÄNDE", it = "SALVATAGGI", es = "PARTIDAS GUARDADAS"),
    "Where should your saves go? If you already play these games in another emulator, pick its save folder (RetroArch's, for one) and carry on with the same saves: a game finds its save by the ROM's file name (.sav or .srm)." to Tr(ja = "セーブを どこに おきますか? ほかの エミュレーターで あそんでいるなら、 その セーブフォルダ (たとえば RetroArchの)を えらべば おなじ セーブで つづけられます: ゲームは ROMの ファイルめい (.sav か .srm)で セーブを さがします。", fr = "Où mettre vos sauvegardes ? Si vous jouez déjà à ces jeux dans un autre émulateur, choisissez son dossier de sauvegardes (celui de RetroArch, par exemple) et continuez avec les mêmes : un jeu trouve sa sauvegarde par le nom de fichier de la ROM (.sav ou .srm).", de = "Wohin mit deinen Speicherständen? Spielst du diese Spiele schon in einem anderen Emulator, wähle seinen Speicherordner (z. B. den von RetroArch) und spiel mit denselben weiter: Ein Spiel findet seinen Speicherstand über den Dateinamen des ROMs (.sav oder .srm).", it = "Dove vanno i salvataggi? Se giochi già a questi giochi in un altro emulatore, scegli la sua cartella dei salvataggi (quella di RetroArch, per esempio) e continua con gli stessi: un gioco trova il suo salvataggio dal nome file della ROM (.sav o .srm).", es = "¿Dónde van tus partidas? Si ya juegas a estos juegos en otro emulador, elige su carpeta de partidas (la de RetroArch, por ejemplo) y sigue con las mismas: cada juego encuentra su partida por el nombre de archivo de la ROM (.sav o .srm)."),
    "KEEP THEM IN POKéDAISY" to Tr(ja = "POKéDAISYに おく", fr = "LES GARDER DANS POKéDAISY", de = "IN POKéDAISY BEHALTEN", it = "TIENILI IN POKéDAISY", es = "GUARDAR EN POKéDAISY"),
    "DEFAULT" to Tr(ja = "ひょうじゅん", fr = "PAR DÉFAUT", de = "STANDARD", it = "PREDEFINITO", es = "POR DEFECTO"),
    "1 SAVE" to Tr(ja = "セーブ 1こ", fr = "1 SAUVEGARDE", de = "1 SPEICHERSTAND", it = "1 SALVATAGGIO", es = "1 PARTIDA"),
    "{0} SAVES" to Tr(ja = "セーブ {0}こ", fr = "{0} SAUVEGARDES", de = "{0} SPEICHERSTÄNDE", it = "{0} SALVATAGGI", es = "{0} PARTIDAS"),
    "CHOOSE ANOTHER FOLDER…" to Tr(ja = "べつの フォルダを えらぶ…", fr = "CHOISIR UN AUTRE DOSSIER…", de = "ANDEREN ORDNER WÄHLEN…", it = "SCEGLI UN'ALTRA CARTELLA…", es = "ELEGIR OTRA CARPETA…"),
    "Choosing a folder asks for All files access first, as games and saves are opened by path." to Tr(ja = "フォルダを えらぶ まえに 「すべての ファイルへの アクセス」を もとめます。 ゲームと セーブは パスで ひらく ためです。", fr = "Choisir un dossier demande d'abord l'accès à tous les fichiers, car jeux et sauvegardes sont ouverts par leur chemin.", de = "Die Ordnerwahl fragt zuerst nach dem Zugriff auf alle Dateien, da Spiele und Speicherstände über ihren Pfad geöffnet werden.", it = "Scegliere una cartella richiede prima l'accesso a tutti i file, perché giochi e salvataggi si aprono dal percorso.", es = "Elegir una carpeta pide primero el acceso a todos los archivos, ya que juegos y partidas se abren por su ruta."),
    "You can change this later in SETTINGS > FOLDERS." to Tr(ja = "あとで せってい > フォルダ で かえられます。", fr = "Vous pourrez le changer plus tard dans OPTIONS > DOSSIERS.", de = "Das kannst du später unter OPTIONEN > ORDNER ändern.", it = "Puoi cambiarlo più tardi in OPZIONI > CARTELLE.", es = "Puedes cambiarlo más tarde en AJUSTES > CARPETAS."),
    "COVER ART (OPTIONAL)" to Tr(ja = "カバー (にんい)", fr = "JAQUETTES (FACULTATIF)", de = "COVER (OPTIONAL)", it = "COPERTINE (FACOLTATIVO)", es = "PORTADAS (OPCIONAL)"),
    "Library covers are box art from RetroAchievements, or icons from SteamGridDB for games it doesn't have. Each needs your own free key: open the site, copy the key and paste it below - one is enough." to Tr(ja = "ライブラリの カバーは RetroAchievementsの パッケージ、 なければ SteamGridDBの アイコンです。 どちらも じぶんの むりょうの キーが ひつようです: サイトを ひらいて キーを コピーし したに はりつけて ください — ひとつで じゅうぶんです。", fr = "Les jaquettes sont les boîtes de RetroAchievements, ou des icônes de SteamGridDB pour les jeux qu'il n'a pas. Chacun demande votre propre clé gratuite : ouvrez le site, copiez la clé et collez-la ci-dessous - une seule suffit.", de = "Bibliothek-Cover sind Verpackungen von RetroAchievements oder Icons von SteamGridDB für Spiele, die es nicht hat. Beide brauchen deinen eigenen kostenlosen Schlüssel: Öffne die Seite, kopiere den Schlüssel und füge ihn unten ein - einer reicht.", it = "Le copertine sono le confezioni di RetroAchievements, o icone di SteamGridDB per i giochi che non ha. Ognuno richiede la tua chiave gratuita: apri il sito, copia la chiave e incollala qui sotto - ne basta una.", es = "Las portadas son cajas de RetroAchievements, o iconos de SteamGridDB para los juegos que no tiene. Cada uno necesita tu propia clave gratis: abre el sitio, copia la clave y pégala abajo - con una basta."),
    "Skip this if you like - you can add a key any time in SETTINGS > COVER ART." to Tr(ja = "スキップしても だいじょうぶ - キーは いつでも せってい > カバー で いれられます。", fr = "Passez si vous voulez - vous pourrez ajouter une clé à tout moment dans OPTIONS > JAQUETTES.", de = "Überspring das ruhig - einen Schlüssel kannst du jederzeit unter OPTIONEN > COVER eingeben.", it = "Saltalo se vuoi - puoi aggiungere una chiave quando vuoi in OPZIONI > COPERTINE.", es = "Omítelo si quieres - puedes añadir una clave cuando quieras en AJUSTES > PORTADAS."),
    "OPEN {0}" to Tr(ja = "{0}を ひらく", fr = "OUVRIR {0}", de = "{0} ÖFFNEN", it = "APRI {0}", es = "ABRIR {0}"),
    "GET KEY" to Tr(ja = "キーを とる", fr = "OBTENIR LA CLÉ", de = "SCHLÜSSEL HOLEN", it = "OTTIENI CHIAVE", es = "OBTENER CLAVE"),
    "SD CARD" to Tr(ja = "SDカード", fr = "CARTE SD", de = "SD-KARTE", it = "SCHEDA SD", es = "TARJETA SD"),
    // In-game HUD (EmulatorEngine / PokeDaisyActivity).
    "Game restarted" to Tr(ja = "ゲームを リスタートしました", fr = "Jeu redémarré", de = "Spiel neu gestartet", it = "Gioco riavviato", es = "Juego reiniciado"),
    "Fast-forward" to Tr(ja = "はやおくり", fr = "Avance rapide", de = "Vorspulen", it = "Avanti veloce", es = "Avance rápido"),
    "Slow-motion ½×" to Tr(ja = "スロー ½×", fr = "Ralenti ½×", de = "Zeitlupe ½×", it = "Rallentatore ½×", es = "Cámara lenta ½×"),
    "Normal speed" to Tr(ja = "ふつうの はやさ", fr = "Vitesse normale", de = "Normale Geschwindigkeit", it = "Velocità normale", es = "Velocidad normal"),
    "Speed {0}×" to Tr(ja = "はやさ {0}×", fr = "Vitesse {0}×", de = "Tempo {0}×", it = "Velocità {0}×", es = "Velocidad {0}×"),
    "Your save changed since you last played here, so the game started from the save file" to Tr(ja = "まえに ここで あそんだあと セーブが かわったので セーブファイルから はじめました", fr = "Ta sauvegarde a changé depuis ta dernière partie ici : le jeu a démarré depuis le fichier de sauvegarde", de = "Dein Spielstand hat sich seit dem letzten Spiel hier geändert, daher startete das Spiel aus der Speicherdatei", it = "Il salvataggio è cambiato dall'ultima partita qui, quindi il gioco è partito dal file di salvataggio", es = "Tu partida cambió desde la última vez que jugaste aquí, así que el juego empezó desde el archivo de guardado"),
)
